import cocotb
from cocotb.triggers import Timer
from rvgen import assemble_rv32im


def assembled_word(source):
    result = assemble_rv32im(source)

    if isinstance(result, int):
        return result & 0xFFFFFFFF
    if isinstance(result, bytes):
        return int.from_bytes(result[:4], byteorder="little")
    if isinstance(result, str):
        return int(result, 0) & 0xFFFFFFFF

    word = result[0]
    if isinstance(word, bytes):
        return int.from_bytes(word, byteorder="little")
    return int(word) & 0xFFFFFFFF


@cocotb.test()
async def test_i_immediate_clear_sign_zero_fills_upper_bits(dut):
    dut.instr.value = assembled_word("addi x1, x0, 7")
    await Timer(1, unit="ns")

    observed = int(dut.imm_i.value)
    assert observed == 0x00000007, (
        f"imm_i: expected 0x00000007 with zero-filled upper bits, "
        f"observed 0x{observed:08X}"
    )
